Method.Source:
protected PriceDisc createPriceDiscInstance(PriceDiscParameters _parameters)
{
    PriceDisc priceDisc = next createPriceDiscInstance(_parameters);

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        priceDisc.parmSalesPurchLineInterface(this.parmSalesPurchLineInterface());
    }

    return priceDisc;
}

protected void retrieveAndSetPriceFields(PriceDisc _priceDisc)
{
    next retrieveAndSetPriceFields(_priceDisc);

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        itemBasePriceRecId = _priceDisc.parmItemBasePriceRecId();
    }
}
